public Mono<OrderSummary> getOrderSummary(String userId) {
    return userRepository.findById(userId)
        .switchIfEmpty(Mono.error(new IllegalArgumentException("User not found: " + userId)))
        .flatMap(user -> orderRepository.findByUserId(user.getId())
            .next() // takes the first order (Flow.first() equivalent)
            .flatMap(order -> enrichmentService.enrich(order)
                .map(enriched -> new OrderSummary(user, enriched))
            )
        );
}

